class CRMLead {
  updatePriorityColor() {
    const priority = this.doc.custom_priority;
    let colorClass = "";
    if (priority === "High") {
      colorClass = "text-red-500";
    } else if (priority === "Medium") {
      colorClass = "text-yellow-500";
    } else if (priority === "Low") {
      colorClass = "text-green-500";
    }
    this.setFieldProperty("custom_priority", "prefix", colorClass);
  }

  onLoad() {
    this.updatePriorityColor();
  }

  onRender() {
    this.updatePriorityColor();
  }

  custom_priority() {
    this.updatePriorityColor();
  }
}
